<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from "vue";
import {
  ApiError, admitPackage, checkPackageAccount, confirmPackageBinding, confirmPackageRealm, confirmPackageSender,
  listConnections, packageAdmissionPrerequisites, preparePackagePlan, reviewPackage, reviewPackagePlan,
  type ConnectionProfile, type PackageAdmissionPrerequisite, type PackageUpload, type PackagePlanReview, type TransferPlan,
} from "./api";

const props = defineProps<{ upload?: PackageUpload }>();
const emit = defineEmits<{ (event: "session-expired"): void; (event: "prepared-plan", plan: TransferPlan): void }>();
const connections = ref<ConnectionProfile[]>([]);
const targetKey = ref("");
const prerequisites = ref<PackageAdmissionPrerequisite>();
const review = ref<PackagePlanReview>();
const busy = ref(false);
const error = ref("");
const notice = ref("");
const senderName = ref("");
const senderUrl = ref("");
const realmForms = ref<Record<string, { display_name: string; external_marker: string }>>({});
const identityForms = ref<Record<string, { target_login: string; credential_ref: string; checked?: { target_account_id: string; credential_checked: boolean } }>>({});
const includeMetadata = ref(true);
const applyMembers = ref(false);
const admitted = ref(false);
let requestGeneration = 0;
let disposed = false;
onBeforeUnmount(() => { disposed = true; ++requestGeneration; });

const target = computed(() => connections.value.find((item) => item.instance_key === targetKey.value));
const packageRef = computed(() => props.upload?.package_ref ?? "");
const digest = computed(() => prerequisites.value?.digest_sha256 ?? props.upload?.package_digest ?? "");
const identities = computed(() => prerequisites.value?.identities ?? []);
const authors = computed(() => identities.value.filter((item) => item.roles.includes("author")));
const authorRefs = computed(() => Object.fromEntries(authors.value.filter((item) => identityForm(item).credential_ref.trim()).map((item) => [item.binding?.binding_id ?? id(item), identityForm(item).credential_ref.trim()] )));
const missingBindingCount = computed(() => review.value?.selection.missing_bindings?.length ?? 0);
const selectionRequest = computed(() => review.value?.selection.request ?? {});
const selectionUnsupported = computed(() => Array.isArray(selectionRequest.value.unsupported_items) ? selectionRequest.value.unsupported_items.map(String) : []);
const reviewedRepositories = computed(() => (Array.isArray(selectionRequest.value.repositories) ? selectionRequest.value.repositories : []) as Array<{ repository: string; teams: Array<{ name: string; permission: string; members: unknown[] }> }>);
const reviewedMetadataCount = computed(() => Array.isArray(selectionRequest.value.metadata) ? selectionRequest.value.metadata.length : 0);
const selectionLimitations = computed(() => Array.isArray(selectionRequest.value.source_limitations) ? selectionRequest.value.source_limitations.map(String) : []);
const canPrepare = computed(() => Boolean(review.value && !missingBindingCount.value && !selectionUnsupported.value.length && !(review.value.selection.missing_credentials?.length) && !(review.value.selection.waiting_parents?.length) && !(review.value.selection.blocked_operations?.length)));

watch(() => props.upload?.package_ref, async (value) => {
  const generation = ++requestGeneration;
  busy.value = false; prerequisites.value = undefined; review.value = undefined; admitted.value = false; error.value = ""; notice.value = ""; targetKey.value = ""; realmForms.value = {}; identityForms.value = {};
  if (!value) return;
  try { const value = await listConnections(); if (!disposed && generation === requestGeneration) connections.value = value; } catch (cause) { if (!disposed && generation === requestGeneration) handleError(cause, "Target connections could not be loaded."); }
}, { immediate: true });
watch(targetKey, () => { ++requestGeneration; busy.value = false; prerequisites.value = undefined; review.value = undefined; admitted.value = false; });
watch([includeMetadata, applyMembers], () => { if (review.value) { review.value = undefined; notice.value = "Plan options changed. Review the selection again before preparing a draft."; } });

function base() { return { target_instance_key: targetKey.value, profile_revision: target.value?.revision ?? -1 }; }
function id(item: PackageAdmissionPrerequisite["identities"][number]): string { const selector = item.selector; return encodeURIComponent(JSON.stringify([selector.realm_key, selector.login, selector.external_id, selector.ou_path])); }
function identityForm(item: PackageAdmissionPrerequisite["identities"][number]) { return identityForms.value[id(item)] ?? (identityForms.value[id(item)] = { target_login: item.binding?.target_login ?? "", credential_ref: "" }); }
function realmForm(key: string) { return realmForms.value[key] ?? (realmForms.value[key] = { display_name: key, external_marker: "" }); }
function checked(item: PackageAdmissionPrerequisite["identities"][number]) { return identityForm(item).checked; }

function ensureTarget(): boolean { if (!target.value) { error.value = "Choose an enabled, locally approved target connection first."; return false; } return true; }
async function loadPrerequisites(): Promise<void> {
  if (!packageRef.value || !ensureTarget()) return; const generation = ++requestGeneration; busy.value = true; error.value = ""; review.value = undefined;
  try { const value = await packageAdmissionPrerequisites(packageRef.value, base()); if (disposed || generation !== requestGeneration) return; prerequisites.value = value; senderName.value = value.sender.instance_key; senderUrl.value = ""; for (const realm of value.realms) realmForms.value[realm.realm_key] ??= { display_name: realm.display_name || realm.realm_key, external_marker: realm.external_marker || "" }; for (const item of value.identities) identityForm(item); }
  catch (cause) { if (!disposed && generation === requestGeneration) handleError(cause, "Package prerequisites could not be loaded."); } finally { if (!disposed && generation === requestGeneration) busy.value = false; }
}
async function confirmSender(): Promise<void> { if (!packageRef.value || !prerequisites.value || !senderName.value.trim() || !senderUrl.value.trim()) return; await refresh(() => confirmPackageSender(packageRef.value, { ...base(), expected_digest: digest.value, display_name: senderName.value.trim(), base_url: senderUrl.value.trim() })); }
async function confirmRealm(realmKey: string): Promise<void> { const form = realmForms.value[realmKey]; if (!form?.display_name.trim() || !form.external_marker.trim()) { error.value = "Enter the explicit local realm display name and external marker."; return; } await refresh(() => confirmPackageRealm(packageRef.value, { ...base(), expected_digest: digest.value, realm_key: realmKey, display_name: form.display_name.trim(), external_marker: form.external_marker.trim() })); }
async function checkAccount(item: PackageAdmissionPrerequisite["identities"][number]): Promise<void> { const form = identityForm(item); if (!form.target_login.trim()) return; const generation = requestGeneration; busy.value = true; error.value = ""; try { const result = await checkPackageAccount(packageRef.value, { ...base(), expected_digest: digest.value, target_login: form.target_login.trim(), credential_ref: form.credential_ref.trim() || null }); if (disposed || generation !== requestGeneration) return; form.checked = result; notice.value = `Account checked: ${result.target_login} (${result.target_account_id}). Confirm the binding separately.`; } catch (cause) { if (!disposed && generation === requestGeneration) handleError(cause, "Target account check failed."); } finally { if (!disposed && generation === requestGeneration) busy.value = false; } }
async function confirmBinding(item: PackageAdmissionPrerequisite["identities"][number]): Promise<void> { const form = identityForms.value[id(item)]; if (!form?.checked || !form.target_login.trim()) return; if (item.roles.includes("author") && !form.credential_ref.trim()) { error.value = "An author binding requires a credential reference."; return; } await refresh(() => confirmPackageBinding(packageRef.value, { ...base(), expected_digest: digest.value, selector: item.selector, target_login: form.target_login.trim(), target_account_id: String(form.checked!.target_account_id), credential_ref: form.credential_ref.trim() || null })); }
async function refresh(operation: () => Promise<PackageAdmissionPrerequisite>): Promise<void> { const generation = ++requestGeneration; busy.value = true; error.value = ""; try { const value = await operation(); if (disposed || generation !== requestGeneration) return; prerequisites.value = value; review.value = undefined; admitted.value = false; notice.value = "Prerequisites refreshed. Review the updated bindings before continuing."; for (const item of value.identities) identityForm(item); } catch (cause) { if (!disposed && generation === requestGeneration) handleError(cause, "The local approval could not be confirmed."); } finally { if (!disposed && generation === requestGeneration) busy.value = false; } }
async function admit(): Promise<void> { if (!packageRef.value || !prerequisites.value || !ensureTarget()) return; const generation = ++requestGeneration; busy.value = true; error.value = ""; try { await reviewPackage(packageRef.value, base()); if (disposed || generation !== requestGeneration) return; await admitPackage(packageRef.value, { ...base(), expected_digest: digest.value }); if (disposed || generation !== requestGeneration) return; admitted.value = true; notice.value = "Package admitted locally. No target data was written."; } catch (cause) { if (!disposed && generation === requestGeneration) handleError(cause, "Package admission could not be completed."); } finally { if (!disposed && generation === requestGeneration) busy.value = false; } }
async function planReview(): Promise<void> { if (!admitted.value) return; const generation = ++requestGeneration; busy.value = true; error.value = ""; try { const value = await reviewPackagePlan(packageRef.value, { ...base(), include_metadata: includeMetadata.value, apply_members: applyMembers.value, author_credential_refs: authorRefs.value }); if (disposed || generation !== requestGeneration) return; review.value = value; notice.value = "Plan review updated. Resolve every blocker before preparing a draft."; } catch (cause) { if (!disposed && generation === requestGeneration) handleError(cause, "Plan review could not be completed."); } finally { if (!disposed && generation === requestGeneration) busy.value = false; } }
async function prepare(): Promise<void> { if (!review.value || !canPrepare.value) return; const generation = ++requestGeneration; busy.value = true; error.value = ""; try { const plan = await preparePackagePlan(packageRef.value, { ...base(), expected_review_digest: review.value.review_digest, include_metadata: includeMetadata.value, apply_members: applyMembers.value, author_credential_refs: authorRefs.value }); if (disposed || generation !== requestGeneration) return; emit("prepared-plan", plan); notice.value = "Draft prepared. It is now available in Transfer plans for review."; } catch (cause) { if (!disposed && generation === requestGeneration) handleError(cause, "The plan draft could not be prepared."); } finally { if (!disposed && generation === requestGeneration) busy.value = false; } }
function invalidateIdentity(item: PackageAdmissionPrerequisite["identities"][number]): void { identityForm(item).checked = undefined; review.value = undefined; }
function handleError(cause: unknown, fallback: string): void { if (cause instanceof ApiError && cause.status === 401) { emit("session-expired"); return; } error.value = cause instanceof ApiError && cause.message ? cause.message : fallback; }
</script>

<template>
  <section v-if="upload?.status === 'ready' && upload.package_ref" class="package-admission-panel" aria-labelledby="admission-title">
    <div class="package-heading"><div><p class="kicker">Guided local admission</p><h2 id="admission-title">Approve package {{ upload.package_ref }}</h2><p class="supporting">Claims from the source are proposals. Every sender, realm, and identity binding below is explicit local evidence.</p></div><button type="button" :disabled="busy" @click="loadPrerequisites">Load prerequisites</button></div>
    <p v-if="error" class="alert" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
    <label for="admission-target">Locally approved target</label><select id="admission-target" v-model="targetKey" :disabled="busy"><option value="">Choose a target</option><option v-for="connection in connections" :key="connection.instance_key" :value="connection.instance_key" :disabled="!connection.enabled || !connection.locally_approved">{{ connection.display_name }} ({{ connection.instance_key }})</option></select>
    <p v-if="target && (!target.enabled || !target.locally_approved)" class="alert">This target is not enabled and locally approved.</p>
    <div v-if="prerequisites" class="admission-content">
      <section class="admission-box"><h3>Package evidence</h3><dl><div><dt>Digest</dt><dd><code>{{ prerequisites.digest_sha256 }}</code></dd></div><div><dt>Repositories</dt><dd>{{ prerequisites.repositories.join(", ") || "None" }}</dd></div><div><dt>Bundle estimate</dt><dd>{{ prerequisites.bundle_bytes.toLocaleString() }} bytes (estimate, not full capacity)</dd></div><div><dt>Metadata</dt><dd>{{ prerequisites.metadata_present ? "Present" : "Not present" }}</dd></div></dl><ul v-if="prerequisites.limitations.length"><li v-for="item in prerequisites.limitations" :key="item">{{ item }}</li></ul></section>
      <section class="admission-box"><h3>Sender proposal</h3><p>{{ prerequisites.sender.instance_key }} · {{ prerequisites.sender.installation_marker }} · <strong>{{ prerequisites.sender.registered ? "Registered" : "Needs local confirmation" }}</strong></p><div v-if="!prerequisites.sender.registered" class="inline-form"><label :for="`sender-name-${upload.package_ref}`">Local sender display name</label><input :id="`sender-name-${upload.package_ref}`" v-model="senderName" :disabled="busy" /><label :for="`sender-url-${upload.package_ref}`">Local sender base URL</label><input :id="`sender-url-${upload.package_ref}`" v-model="senderUrl" type="url" :disabled="busy" /><button type="button" :disabled="busy" @click="confirmSender">Confirm sender locally</button></div></section>
      <section class="admission-box"><h3>Realm proposals</h3><p class="supporting">Native Gitea claims are not LDAP/AD evidence; register the exact realm marker locally when required.</p><div v-for="realm in prerequisites.realms" :key="realm.realm_key" class="mapping-row"><strong>{{ realm.display_name || realm.realm_key }}</strong><span>{{ realm.registered ? "Registered" : "Needs local confirmation" }}</span><template v-if="!realm.registered"><label :for="`realm-name-${realm.realm_key}`">Display name</label><input :id="`realm-name-${realm.realm_key}`" v-model="realmForm(realm.realm_key).display_name" :disabled="busy" /><label :for="`realm-marker-${realm.realm_key}`">External marker</label><input :id="`realm-marker-${realm.realm_key}`" v-model="realmForm(realm.realm_key).external_marker" :disabled="busy" /><button type="button" :disabled="busy" @click="confirmRealm(realm.realm_key)">Confirm realm locally</button></template></div></section>
      <section class="admission-box"><h3>Identity bindings</h3><div v-for="item in identities" :key="id(item)" class="identity-row"><p><strong>{{ item.selector.login }}</strong> · {{ item.selector.realm_key }} · external ID: {{ item.selector.external_id }} · OU: {{ item.selector.ou_path || "(empty)" }} · roles: {{ item.roles.join(", ") }}</p><p v-if="item.binding">Already bound to {{ item.binding.target_login }} (account {{ item.binding.target_account_id }})</p><label v-if="item.roles.includes('author')" :for="`credential-${id(item)}`">Author credential reference (token value is never stored here)</label><input v-if="item.roles.includes('author')" :id="`credential-${id(item)}`" v-model="identityForm(item).credential_ref" autocomplete="off" :disabled="busy" @input="invalidateIdentity(item)" /><template v-if="!item.binding"><label :for="`target-login-${id(item)}`">Target login</label><input :id="`target-login-${id(item)}`" v-model="identityForm(item).target_login" :disabled="busy" @input="invalidateIdentity(item)" /><div class="actions"><button type="button" :disabled="busy || !identityForm(item).target_login" @click="checkAccount(item)">Check target account</button><button type="button" :disabled="busy || !identityForm(item).checked" @click="confirmBinding(item)">Confirm binding</button></div><p v-if="identityForm(item).checked" class="notice">Account {{ checked(item)!.target_account_id }} checked ({{ checked(item)!.credential_checked ? "credential checked" : "no author credential check" }}). Confirm separately.</p></template></div></section>
      <section class="admission-box"><h3>Admit and review plan</h3><p>Admission records package facts only. It does not write target data.</p><button class="primary" type="button" :disabled="busy || !prerequisites.sender.registered || prerequisites.realms.some((realm) => !realm.registered)" @click="admit">{{ admitted ? "Admitted locally" : "Admit package locally" }}</button><div class="plan-options"><label><input v-model="includeMetadata" type="checkbox" :disabled="busy" /> Include metadata</label><label><input v-model="applyMembers" type="checkbox" :disabled="busy" /> Apply team/member changes</label><p class="supporting">For a structure/Git-only plan, clear both options. Author bindings still require credential references.</p><button type="button" :disabled="busy || !admitted" @click="planReview">Review plan selection</button></div></section>
      <section v-if="review" class="admission-box"><h3>Plan review</h3><p>Review digest: <code>{{ review.review_digest }}</code></p><dl><div><dt>Repositories</dt><dd><ul><li v-for="repository in reviewedRepositories" :key="repository.repository">{{ repository.repository }}</li></ul></dd></div><div><dt>Teams and permissions</dt><dd><ul><template v-for="repository in reviewedRepositories" :key="repository.repository"><li v-for="team in repository.teams" :key="team.name">{{ repository.repository }} · {{ team.name }} · {{ team.permission }} · {{ team.members.length }} mapped members</li></template></ul></dd></div><div><dt>Metadata</dt><dd>{{ reviewedMetadataCount }} selected issues/comments</dd></div><div><dt>Source limitations</dt><dd>{{ selectionLimitations.join(", ") || "None" }}</dd></div><div><dt>Missing bindings</dt><dd>{{ review.selection.missing_bindings.join(", ") || "None" }}</dd></div><div><dt>Missing credentials</dt><dd>{{ review.selection.missing_credentials.join(", ") || "None" }}</dd></div><div><dt>Waiting parents</dt><dd>{{ review.selection.waiting_parents.join(", ") || "None" }}</dd></div><div><dt>Blocked operations</dt><dd>{{ review.selection.blocked_operations.join(", ") || "None" }}</dd></div></dl><p v-if="selectionUnsupported.length" class="alert">Unsupported items: {{ selectionUnsupported.join(", ") }}</p><p v-if="!canPrepare" class="alert">Resolve the blockers above before preparing a draft.</p><button class="primary" type="button" :disabled="busy || !canPrepare" @click="prepare">Prepare draft for Transfer plans</button></section>
    </div>
  </section>
</template>

<style scoped>
.package-heading { display:flex; justify-content:space-between; align-items:flex-start; gap:1rem; }
.package-admission-panel > label { display:block; margin:.75rem 0 .4rem; font-weight:700; }
.package-admission-panel > select { width:100%; min-height:2.9rem; padding:.65rem .75rem; border:1px solid #829187; border-radius:.25rem; background:#fff; color:#18221c; font:inherit; }
.plan-options label { display:flex; align-items:center; gap:.65rem; min-height:2.75rem; }
.plan-options input[type=checkbox] { width:1.15rem; height:1.15rem; min-height:0; padding:0; flex:0 0 auto; }

.package-admission-panel { margin-top: 2rem; padding-top: 1.5rem; border-top: .0625rem solid #ccd4cd; }.admission-content { display: grid; gap: 1rem; margin-top: 1rem; }.admission-box { overflow-wrap:anywhere; padding: 1rem; border: .0625rem solid #c6d2c8; background: #fbfcfa; }.admission-box h3 { margin-top: 0; }.admission-box dl { display: grid; gap: .4rem; }.admission-box dl div { display: grid; grid-template-columns: minmax(8rem, auto) minmax(0, 1fr); gap: .75rem; }.admission-box dt { font-weight: 700; color: #526057; }.admission-box dd { margin: 0; overflow-wrap: anywhere; }.inline-form, .identity-row, .mapping-row { display: grid; gap: .45rem; margin-top: .75rem; padding-top: .75rem; border-top: .0625rem solid #d7dfd8; }.mapping-row { grid-template-columns: minmax(10rem, 1fr) auto; }.mapping-row label, .mapping-row input, .mapping-row button { grid-column: 1 / -1; }.identity-row p { margin: 0; }.plan-options { display: grid; gap: .6rem; margin-top: 1rem; }.notice { color: #315d43; }@media (max-width:48rem) { .package-heading { flex-direction: column; } }
</style>
